// Generates AppTranslationKeys and the AppL10n resolver from the AppLocalizations
// class that `flutter gen-l10n` builds from lib/l10n/app_en.arb.
//
// Run from the project root after `flutter gen-l10n`:
//   dart run tool/l10n_keys_generator_helper.dart
import 'dart:io';

/// Source generated by `flutter gen-l10n`; the single source of message names and parameters.
const String localizationsPath = 'lib/l10n/app_localizations.dart';

/// Output folder of the generated Dart files.
const String _helpersFolder = 'lib/helpers';

/// Generated file holding the AppTranslationKeys constants.
const String _keysPath = '$_helpersFolder/app_translation_keys.dart';

/// Keeps every resolver function and file under fCheck's size limits (2 lines per case).
const int _maxCasesPerResolverFile = 300;

/// First line of every generated file.
const String _generatedHeader =
    '// Generated by tool/l10n_keys_generator_helper.dart from lib/l10n/app_en.arb; do not edit by hand.';

/// Matches the abstract getters and methods declared on AppLocalizations, in declaration order.
final RegExp _declarationPattern = RegExp(r'^  String (?:get (\w+)|(\w+)\(([^)]*)\));$', multiLine: true);

/// Matches the resolver continuation files, so stale ones can be removed.
final RegExp _resolverStageFilePattern = RegExp(r'app_l10n_resolver_stage\d+_helper\.dart$');

/// One localized message of AppLocalizations: its name and parameter names in call order.
class L10nMessage {
  /// Creates a message description.
  const L10nMessage(this.name, this.parameters);

  /// Getter or method name on AppLocalizations, also used as the translation key.
  final String name;

  /// Parameter names, in the order the generated method expects them.
  final List<String> parameters;
}

/// Returns every generated file (path to content) for [messages].
Map<String, String> buildGeneratedSources(List<L10nMessage> messages) {
  final Map<String, String> sources = <String, String>{_keysPath: _buildKeysSource(messages)};
  final int chunkCount = (messages.length / _maxCasesPerResolverFile).ceil();
  for (int chunk = 0; chunk < chunkCount; chunk++) {
    final int start = chunk * _maxCasesPerResolverFile;
    final int end = (start + _maxCasesPerResolverFile).clamp(0, messages.length);
    sources[_resolverPath(chunk)] = _buildResolverSource(messages.sublist(start, end), chunk, chunkCount);
  }
  return sources;
}

/// Returns true when [path] is a resolver continuation file that generation can own.
bool isResolverStageFile(String path) => _resolverStageFilePattern.hasMatch(path);

/// Writes the generated files, removes stale resolver files, then formats the output.
void main() {
  final Map<String, String> sources = buildGeneratedSources(parseMessages(File(localizationsPath).readAsStringSync()));

  for (final FileSystemEntity entity in Directory(_helpersFolder).listSync()) {
    if (isResolverStageFile(entity.path) && !sources.containsKey(entity.path)) {
      entity.deleteSync();
    }
  }
  sources.forEach((String path, String content) => File(path).writeAsStringSync(content));

  final ProcessResult result = Process.runSync('dart', <String>['format', ...sources.keys]);
  if (result.exitCode != 0) {
    stderr.write(result.stderr);
    exit(result.exitCode);
  }
  stdout.writeln('Generated ${sources.length} files.');
}

/// Parses the message getters and methods declared in the AppLocalizations [source].
List<L10nMessage> parseMessages(String source) {
  return _declarationPattern.allMatches(source).map((RegExpMatch match) {
    final String? getterName = match.group(1);
    if (getterName != null) {
      return L10nMessage(getterName, const <String>[]);
    }
    final List<String> parameters = match
        .group(3)!
        .split(',')
        .map((String parameter) => parameter.trim().split(' '))
        .map((List<String> typeAndName) {
          if (typeAndName.first != 'String' && typeAndName.first != 'Object') {
            throw StateError('Unsupported placeholder type in ${match.group(2)}: ${typeAndName.first}');
          }
          return typeAndName.last;
        })
        .toList();
    return L10nMessage(match.group(2)!, parameters);
  }).toList();
}

/// Returns the AppTranslationKeys source declaring one constant per message.
String _buildKeysSource(List<L10nMessage> messages) {
  final StringBuffer buffer = StringBuffer()
    ..writeln(_generatedHeader)
    ..writeln()
    ..writeln('/// Defines shared translation key constants to avoid inline literal keys.')
    ..writeln('abstract class AppTranslationKeys {')
    ..writeln('  /// Prevents instantiation of translation keys.')
    ..writeln('  AppTranslationKeys._();')
    ..writeln()
    ..writeln('  /// Translation keys used across the application UI.');
  for (final L10nMessage message in messages) {
    buffer.writeln("  static const String ${message.name} = '${message.name}';");
  }
  buffer.writeln('}');
  return buffer.toString();
}

/// Returns one resolver file: a switch over [messages] that hands unknown keys to the next stage.
String _buildResolverSource(List<L10nMessage> messages, int chunk, int chunkCount) {
  final bool isLast = chunk == chunkCount - 1;
  final StringBuffer buffer = StringBuffer()
    ..writeln(_generatedHeader)
    ..writeln();
  if (!isLast) {
    buffer.writeln("import 'package:money/helpers/${_resolverFileName(chunk + 1)}';");
  }
  buffer
    ..writeln("import 'package:money/helpers/app_translation_keys.dart';")
    ..writeln("import 'package:money/l10n/app_localizations.dart';")
    ..writeln()
    ..writeln(
      chunk == 0
          ? '/// Resolves translation [key] for AppL10n with placeholder values from [p]; returns [key] when unknown.'
          : '/// Continues [resolveAppL10nKey] for the keys of stage ${chunk + 1}; returns [key] when unknown.',
    )
    ..writeln('String ${_resolverFunctionName(chunk)}(AppLocalizations l10n, String key, Map<String, String> p) {')
    ..writeln('  switch (key) {');
  for (final L10nMessage message in messages) {
    final String call = message.parameters.isEmpty
        ? message.name
        : '${message.name}(${message.parameters.map((String name) => "p['$name'] ?? ''").join(', ')})';
    buffer
      ..writeln('    case AppTranslationKeys.${message.name}:')
      ..writeln('      return l10n.$call;');
  }
  buffer
    ..writeln('    default:')
    ..writeln(isLast ? '      return key;' : '      return ${_resolverFunctionName(chunk + 1)}(l10n, key, p);')
    ..writeln('  }')
    ..writeln('}');
  return buffer.toString();
}

/// Resolver file name for [chunk]; the first chunk keeps the historical entry-point file.
String _resolverFileName(int chunk) =>
    chunk == 0 ? 'app_l10n_resolver_helper.dart' : 'app_l10n_resolver_stage${chunk + 1}_helper.dart';

/// Resolver function name for [chunk]; the first chunk is the public entry point.
String _resolverFunctionName(int chunk) => chunk == 0 ? 'resolveAppL10nKey' : 'resolveAppL10nKeyStage${chunk + 1}';

/// Resolver file path for [chunk].
String _resolverPath(int chunk) => '$_helpersFolder/${_resolverFileName(chunk)}';
